//! `cargo xtask parity [--check] [--out PATH]`: writes `docs/command-reference.md` from the
//! engine catalog and the device command grammar, so the reference never drifts from the code.

use std::path::Path;

#[cfg(feature = "engine")]
pub fn render() -> String {
    use packetcraft_ios::grammar::{Modes, SPECS, Tok};
    let mut s = String::from(
        "# Command reference\n\n_Generated by `cargo xtask parity` from `crates/engine/src/catalog.rs` and `crates/ios/src/grammar.rs`; do not edit by hand._\n\n## Engine commands\n\nEvery front end (UI, `packetcraft-cli run`, MCP `packetcraft_run`) runs these.\n\n| Id | Label | Menu | Shortcut | Parameters |\n|---|---|---|---|---|\n",
    );
    for c in packetcraft_engine::CATALOG {
        s.push_str(&format!("| `{}` | {} | {} | {} | `{}` |\n", c.id, c.label, c.menu, c.shortcut.unwrap_or(""), c.params.replace('|', "\\|")));
    }
    s.push_str("\n## Device console (routers and switches)\n\nWords may be abbreviated to any unambiguous prefix. `?` lists what can follow; Tab completes.\n\n| Command | Modes | Devices | What it does |\n|---|---|---|---|\n");
    for spec in SPECS {
        let words: Vec<String> = spec
            .path
            .iter()
            .map(|t| match t {
                Tok::K(k) => k.to_string(),
                Tok::Arg(a) | Tok::Rest(a) => a.replace('|', "\\|"),
            })
            .collect();
        let modes: Vec<&str> = [
            (Modes::USER, "user"),
            (Modes::EXEC, "privileged"),
            (Modes::CONFIG, "config"),
            (Modes::IF, "interface"),
            (Modes::SUBIF, "subinterface"),
            (Modes::VLAN, "vlan"),
        ]
        .iter()
        .filter(|(m, _)| spec.modes.has(*m))
        .map(|(_, n)| *n)
        .collect();
        let devices = match (spec.devices.has(Modes::ROUTER), spec.devices.has(Modes::SWITCH)) {
            (true, true) => "router, switch",
            (true, false) => "router",
            _ => "switch",
        };
        s.push_str(&format!("| `{}` | {} | {devices} | {} |\n", words.join(" "), modes.join(", "), spec.help));
    }
    s.push_str("\n## Host shell (PCs and servers)\n\n```text\n");
    s.push_str(packetcraft_ios::host::HELP);
    s.push_str("\n```\n");
    s
}

#[cfg(feature = "engine")]
pub fn run(root: &Path, args: &[&str]) -> Result<(), String> {
    let check = args.contains(&"--check");
    let out = args
        .iter()
        .position(|a| *a == "--out")
        .and_then(|i| args.get(i + 1))
        .map_or_else(|| root.join("docs/command-reference.md"), |p| root.join(p));
    let text = render();
    if check {
        let current = std::fs::read_to_string(&out).unwrap_or_default();
        if current != text {
            return Err(format!("{} is stale: run `cargo xtask parity`", out.display()));
        }
        println!("parity: {} is up to date", out.display());
        return Ok(());
    }
    std::fs::write(&out, text).map_err(|e| format!("{}: {e}", out.display()))?;
    println!("parity: wrote {}", out.display());
    Ok(())
}

#[cfg(not(feature = "engine"))]
pub fn run(_: &Path, _: &[&str]) -> Result<(), String> {
    Err("built without the `engine` feature".into())
}
